// productsBase is the generated base of table products. It holds the table (t),
// typed predicates (where), helpers that run in the context transaction and
// return the model rows, and the pkg/db/transactor functions as methods.
// Embed it in the implementation and set it with newProductsBase(db).
type productsBase struct {
	db    qrm.DB
	t     *table.ProductsTable
	where productsWhere
}

// newProductsBase returns the base of table products. It runs its statements on the
// transaction of the context, and on db outside one.
